        /// <summary>A match (re.Match): groups by number or name, positions, the matched string.</summary>
        internal sealed class Match : IPyRepr
        {
            readonly NetMatch _m;
            public readonly Pattern re;
            public readonly string @string;
            public readonly long pos, endpos;

            internal Match(NetMatch m, Pattern re, string s, long pos, long endpos) { _m = m; this.re = re; @string = s; this.pos = pos; this.endpos = endpos; }

            int Index(object? g)
            {
                int i = g switch
                {
                    null => 0,
                    string name => re.groupindex.TryGetValue(name, out var ix) ? (int)ix : throw new IndexOutOfRangeException("no such group"),
                    bool b => b ? 1 : 0,
                    _ => (int)Convert.ToInt64(g, System.Globalization.CultureInfo.InvariantCulture),
                };
                if (i < 0 || i > re.groups) throw new IndexOutOfRangeException("no such group");
                return i;
            }
            NetGroup G(object? g) => _m.Groups[Index(g)];

            public string group() => _m.Value;
            public string? group(object? g) { var gr = G(g); return gr.Success ? gr.Value : null; }
            public PyTuple<string?> group(object? g1, object? g2, params object?[] more) =>
                new PyTuple<string?>(new[] { g1, g2 }.Concat(more).Select(group).ToArray());
            public string? this[object? g] => group(g);

            public PyTuple<string?> groups(string? @default = null) =>
                new PyTuple<string?>(Enumerable.Range(1, (int)re.groups).Select(i => _m.Groups[i].Success ? _m.Groups[i].Value : @default).ToArray());
            public OrderedDictionary<string, string?> groupdict(string? @default = null)
            {
                var d = new OrderedDictionary<string, string?>();
                foreach (var kv in re.groupindex) { var gr = _m.Groups[(int)kv.Value]; d[kv.Key] = gr.Success ? gr.Value : @default; }
                return d;
            }

            public long start(object? g = null) { var gr = G(g); return gr.Success ? gr.Index : -1; }
            public long end(object? g = null) { var gr = G(g); return gr.Success ? gr.Index + gr.Length : -1; }
            public (long, long) span(object? g = null) => (start(g), end(g));

            /// <summary>The number of the last group that matched (the one that closed last), or None.</summary>
            public long? lastindex
            {
                get
                {
                    long? best = null; int bestEnd = -1;
                    for (int i = 1; i <= re.groups; i++)
                    {
                        var gr = _m.Groups[i];
                        if (gr.Success && gr.Index + gr.Length > bestEnd) { best = i; bestEnd = gr.Index + gr.Length; }
                    }
                    return best;
                }
