            public string? lastgroup => lastindex is long li ? re.groupindex.FirstOrDefault(kv => kv.Value == li).Key : null;

            public string expand(string template) => Template.Parse(template, re).Expand(this);

            public string __repr__() => $"<re.Match object; span=({start()}, {end()}), match={Builtins.repr(group())}>";
            public override string ToString() => __repr__();
        }

        /// <summary>A replacement template: literal text and group references (\1, \g&lt;name&gt;, \g&lt;0&gt;), with Python's escapes.</summary>
        sealed class Template
        {
            readonly List<object> _parts = new List<object>(); // string or int (group number)

            public static Template Parse(string repl, Pattern p)
            {
                var t = new Template();
                var lit = new StringBuilder();
                void Flush() { if (lit.Length > 0) { t._parts.Add(lit.ToString()); lit.Clear(); } }
                for (int i = 0; i < repl.Length; i++)
                {
                    char c = repl[i];
                    if (c != '\\' || i + 1 >= repl.Length) { lit.Append(c); continue; }
                    char e = repl[++i];
                    if (e == 'g' && i + 1 < repl.Length && repl[i + 1] == '<')
                    {
                        int close = repl.IndexOf('>', i + 2);
                        if (close < 0) throw new error("missing >, unterminated name", repl, i);
                        string name = repl.Substring(i + 2, close - i - 2);
                        int g = int.TryParse(name, out var num) ? num : p.groupindex.TryGetValue(name, out var gi) ? (int)gi : throw new IndexOutOfRangeException($"unknown group name '{name}'");
                        if (g > p.groups) throw new error($"invalid group reference {g}", repl, i);
                        Flush(); t._parts.Add(g);
                        i = close;
                    }
                    else if (char.IsAsciiDigit(e))
                    {
                        int g = e - '0';
                        if (i + 1 < repl.Length && char.IsAsciiDigit(repl[i + 1]) && g * 10 + (repl[i + 1] - '0') <= p.groups) g = g * 10 + (repl[++i] - '0');
                        if (g > p.groups) throw new error($"invalid group reference {g}", repl, i);
                        Flush(); t._parts.Add(g);
                    }
                    else
                    {
                        switch (e)
                        {
                            case 'n': lit.Append('\n'); break;
                            case 't': lit.Append('\t'); break;
                            case 'r': lit.Append('\r'); break;
                            case 'f': lit.Append('\f'); break;
                            case 'v': lit.Append('\v'); break;
                            case 'a': lit.Append('\a'); break;
                            case 'b': lit.Append('\b'); break;
                            case '\\': lit.Append('\\'); break;
                            default:
                                if (char.IsAsciiLetter(e)) throw new error($"bad escape \\{e}", repl, i - 1);
                                lit.Append('\\').Append(e); // \& and other unknown non-letter escapes stay as written
                                break;
                        }
                    }
                }
                Flush();
                return t;
            }

            public string Expand(Match m)
            {
                if (_parts.Count == 1 && _parts[0] is string only) return only;
                var sb = new StringBuilder();
                foreach (var part in _parts) sb.Append(part is string s ? s : m.group((long)(int)part) ?? "");
                return sb.ToString();
            }
        }

        /// <summary>
        /// Python regex syntax → .NET's. Named groups become plain numbered groups (the names kept on the side), so every
        /// group has its Python number: .NET would number named groups after all unnamed ones.
        /// </summary>
        static string Translate(string p, ref long flags, out int groupCount, out OrderedDictionary<string, long> names)
        {
            names = new OrderedDictionary<string, long>();
            groupCount = 0;
            var sb = new StringBuilder(p.Length + 8);
            bool inClass = false;
            // global inline flags at the very start: (?aimsux)
            var lead = System.Text.RegularExpressions.Regex.Match(p, @"^\(\?([aiLmsux]+)\)");
            if (lead.Success)
            {
                foreach (char f in lead.Groups[1].Value)
                    flags |= f switch { 'a' => ASCII, 'i' => IGNORECASE, 'L' => LOCALE, 'm' => MULTILINE, 's' => DOTALL, 'u' => UNICODE, 'x' => VERBOSE, _ => 0 };
                p = p.Substring(lead.Length);
            }
            bool ascii = (flags & ASCII) != 0, verbose = (flags & VERBOSE) != 0;
            for (int i = 0; i < p.Length; i++)
            {
                char c = p[i];
                if (c == '\\' && i + 1 < p.Length)
                {
                    char e = p[++i];
                    if (inClass)
                    {
                        if (ascii && e == 'd') sb.Append("0-9");
                        else if (ascii && e == 'w') sb.Append("a-zA-Z0-9_");
                        else if (ascii && e == 's') sb.Append(@" \t\n\r\f\v");
                        else sb.Append('\\').Append(e);
                        continue;
                    }
                    switch (e)
                    {
                        case 'Z': sb.Append(@"\z"); break;
                        case 'd' when ascii: sb.Append("[0-9]"); break;
                        case 'D' when ascii: sb.Append("[^0-9]"); break;
                        case 'w' when ascii: sb.Append("[a-zA-Z0-9_]"); break;
                        case 'W' when ascii: sb.Append("[^a-zA-Z0-9_]"); break;
                        case 's' when ascii: sb.Append(@"[ \t\n\r\f\v]"); break;
                        case 'S' when ascii: sb.Append(@"[^ \t\n\r\f\v]"); break;
                        case 'U':
                            if (p.Length - i - 1 >= 8 && int.TryParse(p.AsSpan(i + 1, 8), System.Globalization.NumberStyles.HexNumber, null, out var cp))
                            {
                                sb.Append(NetRegex.Escape(char.ConvertFromUtf32(cp)));
                                i += 8;
                            }
                            else sb.Append(@"\U");
                            break;
                        default: sb.Append('\\').Append(e); break;
                    }
                    continue;
                }
                if (inClass)
                {
                    if (c == ']') { inClass = false; sb.Append(']'); }
                    else if (c == '[') sb.Append(@"\["); // literal in Python; .NET could read -[...] as class subtraction
                    else sb.Append(c);
                    continue;
                }
                if (verbose && c == '#')
                {
                    int nl = p.IndexOf('\n', i);
                    int stop = nl < 0 ? p.Length : nl;
                    sb.Append(p, i, stop - i);
                    i = stop - 1;
                    continue;
                }
                switch (c)
                {
                    case '[':
                        inClass = true;
                        sb.Append('[');
                        if (i + 1 < p.Length && p[i + 1] == '^') { sb.Append('^'); i++; }
                        if (i + 1 < p.Length && p[i + 1] == ']') { sb.Append(@"\]"); i++; }
                        break;
                    case '(':
                        if (i + 1 < p.Length && p[i + 1] == '?')
                        {
                            if (i + 2 < p.Length && p[i + 2] == 'P' && i + 3 < p.Length && p[i + 3] == '<')
                            {
                                int close = p.IndexOf('>', i + 4);
                                if (close < 0) throw new error("missing >, unterminated name", p, i);
                                names[p.Substring(i + 4, close - i - 4)] = ++groupCount;
                                sb.Append('(');
                                i = close;
                            }
                            else if (i + 2 < p.Length && p[i + 2] == 'P' && i + 3 < p.Length && p[i + 3] == '=')
                            {
                                int close = p.IndexOf(')', i + 4);
                                if (close < 0) throw new error("missing ), unterminated name", p, i);
                                string name = p.Substring(i + 4, close - i - 4);
                                if (!names.TryGetValue(name, out var g)) throw new error($"unknown group name '{name}'", p, i);
                                sb.Append(@"\k<").Append(g).Append('>');
                                i = close;
                            }
                            else if (i + 2 < p.Length && p[i + 2] == '(')
                            {
                                // (?(name)yes|no) / (?(1)yes|no)
                                int close = p.IndexOf(')', i + 3);
                                string cond = close < 0 ? "" : p.Substring(i + 3, close - i - 3);
                                sb.Append("(?(").Append(names.TryGetValue(cond, out var cg) ? cg.ToString() : cond).Append(')');
                                i = close;
                            }
                            else if (i + 2 < p.Length && "aiLmsux-".IndexOf(p[i + 2]) >= 0)
                            {
                                // scoped inline flags (?i:...) / (?-i:...): .NET has no a, L, u
                                int j = i + 2;
                                var kept = new StringBuilder();
                                while (j < p.Length && "aiLmsux-".IndexOf(p[j]) >= 0) { if ("aLu".IndexOf(p[j]) < 0) kept.Append(p[j]); j++; }
                                string k = kept.ToString().TrimEnd('-');
                                if (j < p.Length && p[j] == ':') sb.Append(k.Length > 0 ? "(?" + k + ":" : "(?:");
                                else sb.Append(k.Length > 0 ? "(?" + k + ")" : "(?:)");
                                i = j;
                            }
                            else sb.Append('('); // (?: (?= (?! (?<= (?<! (?> (?#
                        }
                        else { groupCount++; sb.Append('('); }
                        break;
                    case '{':
                        // {,n} means {0,n} in Python
                        if (i + 1 < p.Length && p[i + 1] == ',' && System.Text.RegularExpressions.Regex.IsMatch(p.Substring(i), @"^\{,\d+\}")) sb.Append("{0");
                        else sb.Append('{');
                        break;
                    default: sb.Append(c); break;
                }
            }
            return sb.ToString();
        }
